     ,cspu_id
     ,model_id
     ,item_id
     ,shop_id
FROM srdi_mart.dim_sr_data_warehouse_pb_all_cspu_link_analysis_hf
WHERE grass_region = ${grass_region}
  AND local_date = ${local_date}
;
--sql_divide_splitter--

create temporary view traffic_raw_${grass_region_without_quote} as
select local_hour
     ,model_id
     ,sum(order_cnt) order_cnt
from srdi_mart.dws_sr_data_warehouse_tc_pb_basic_aggr_1d
where grass_region = ${grass_region}
  and local_date = ${local_date}
  and mapping_general = '__ALL__'
group by 1,2
;
--sql_divide_splitter--

create temporary view winner_${grass_region_without_quote} as
select model_id
from srdi_mart.dim_sr_data_warehouse_pb_one_variation_model_analysis_hf
where grass_region = ${grass_region}
  AND local_date = ${local_date}
  and business_type in (3,4)
group by 1
;
--sql_divide_splitter--

INSERT OVERWRITE TABLE ${schema}.dws_sr_data_warehouse_tc_pb_winner_order_1d
partition(grass_region = ${grass_region}, local_date = ${local_date})
SELECT cspu_id
     ,a.model_id
     ,item_id
     ,shop_id
     ,max(if(c.model_id is not null, 1, 0)) is_win_day
     ,coalesce(sum(order_cnt),0) as order_cnt
from all_cspu_model_${grass_region_without_quote} a
left join traffic_raw_${grass_region_without_quote} b
on a.local_hour = b.local_hour
and a.model_id = b.model_id
left join winner_${grass_region_without_quote} c
on a.model_id = c.model_id
group by 1,2,3,4
;
